[CmdletBinding()]
param(
    [Parameter(Mandatory = $false)][string] $Channel = "3.1",
    [Parameter(Mandatory = $false)][string] $BranchName = "",
    [Parameter(Mandatory = $false)][string] $CommitMessage = "",
